#!/bin/bash
# Build 26: upstream nx2 17baed71 (#1236 white light fix) with the unbacked image fix,
# #313 on shader cache v2, 128 query banks and PR #1023.
set -eux
UP=${UPSTREAM:-https://github.com/zortos293/lichii}
if [ -z "${LOCAL_ONLY:-}" ]; then
  git fetch -q "$UP" 17baed716da04fd743fbd8f9604bec96eab0a123
fi
git checkout -q --detach 17baed716da04fd743fbd8f9604bec96eab0a123
echo "" | base64 -d | xz -d > "${RUNNER_TEMP:-/tmp}/b26.diff"
git apply --index "${RUNNER_TEMP:-/tmp}/b26.diff"
git commit -q -m "Build 26 changes: unbacked image fix (e15125b), #313 on shader cache v2, 128 query banks, PR #1023"
test "$(git rev-parse 'HEAD^{tree}')" = ee5b96235d34f97c0fb033eef15cf2f5f5ca2ea6
for f in $(git ls-tree -r --name-only HEAD .github); do
  git cat-file -e "fork_tip:$f" 2>/dev/null || git rm -q "$f"
done
git checkout fork_tip -- .github
git commit -q -m "Keep this fork's workflow files" || true
test -z "$(git diff fork_tip HEAD -- .github)"
TREE=$(git rev-parse 'HEAD^{tree}')
echo "final tree $TREE"
NEW=$(git commit-tree "$TREE" -p fork_tip -p HEAD -m "Build 26: upstream nx2 17baed71 (#1236 white light fix) with the unbacked image fix, #313, 128 query banks and #1023")
git checkout -q --detach "$NEW"
